import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = [int(v) for v in data[1:1 + n]]
    ans = [0] * n
    for j in range(n):
        for i in range(j):
            if ans[i] == 0 and a[j] > a[i]:
                ans[i] = j - i
    print(' '.join(str(v) for v in ans))


main()
